hold_ticks := 0
if ((#Bedroom_Temp).temperatureSensor_temperature > 28) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 300) {
(#Bedroom_Fan).switch_on()
        break
}
}
else {
hold_ticks = 0
}
delay(20 MIN)
(#Bedroom_Fan).switch_off()

